mapper.select:
SELECT fair_date_id, fair_id, operation_date, capacity, entry_start_time, entry_end_time, created_at, updated_at
  FROM fair_dates
 WHERE fair_date_id = #{fairDateId}

SELECT fair_date_id, fair_id, operation_date, capacity, entry_start_time, entry_end_time, created_at, updated_at
  FROM fair_dates
 WHERE fair_id = #{fairId}
   AND operation_date = #{operationDate}

mapper.update:
UPDATE fair_dates
   SET capacity = #{capacity},
       entry_start_time = #{entryStartTime},
       entry_end_time = #{entryEndTime},
       updated_at = #{updatedAt}
 WHERE fair_date_id = #{fairDateId}
